const out = [];
for (let i = 0; i < 10; i++) {
  if (window.__ensemble.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break;
  out.push(b.textContent.trim().slice(0, 30));
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
return 'clicked: ' + out.join(' > ');

window.__S = () => window.__ensemble.getState();
window.__sleep = (ms) => new Promise(r => setTimeout(r, ms));
window.__busy = () => Object.values(window.__S().agents).filter(a => a.chatId === window.__S().chatId && a.phase !== 'idle' && a.phase !== 'error').length;
window.__waitIdle = async (max) => { const t0 = Date.now(); while (Date.now() - t0 < max) { await window.__sleep(500); if (window.__busy() === 0) return Math.round((Date.now() - t0) / 1000) + 's'; } return 'still busy'; };
window.__bottom = () => { const sc = document.querySelector('[data-view-scope]')?.parentElement; if (sc) sc.scrollTop = sc.scrollHeight; };
window.__info = () => { const s = window.__S(); const c = s.chats.find(c => c.id === s.chatId); const ag = c.agents || []; const depth = Math.max(0, ...ag.map(a => a.spawned?.depth || 0)); const t = s.tasks[c.id] || []; return 'agents ' + ag.length + ' (gone ' + ag.filter(a => a.spawned?.gone).length + ') depth ' + depth + ' tasks ' + t.length + ' done ' + t.filter(x => x.status === 'done').length + ' busy ' + window.__busy() + ' view ' + s.view + ' neurons ' + document.querySelectorAll('.nn-node').length; };
window.__hover = (name) => { const g = [...document.querySelectorAll('.nn-node')].find(x => (x.getAttribute('aria-label') || '').startsWith(name)) || [...document.querySelectorAll('.nn-node')][3]; if (g) g.dispatchEvent(new MouseEvent('mouseover', { bubbles: true, relatedTarget: document.body })); return g ? g.getAttribute('aria-label') : 'none'; };
return 'helpers';

const st = window.__ensemble; const s = st.getState(); const chatId = s.chatId; const now = Date.now();
const chat = s.chats.find(c => c.id === chatId); const have = (chat.agents || []).filter(a => !a.spawned?.gone);
const lead = chat.leadId || s.settings.leadId || s.accounts.find(a => a.enabled).id;
const byName = n => have.find(a => a.name === n);
const accents = ['teal', 'blue', 'violet', 'green', 'amber', 'rose', 'slate', 'clay'];
const extra = []; const tasks = []; let k = 0;
const mk = (name, by, depth, role) => { const a = { id: 'sx-' + (k++), name, provider: 'claude', accent: accents[k % 8], enabled: true, model: null, effort: null, role, createdAt: now, configDir: null, spawned: { chatId, base: lead, by, depth, at: now } }; extra.push(a); return a; };
const task = (from, to, status, title, after) => { const t = { id: 'sxt-' + tasks.length, chatId, title, brief: title, from, to, status, createdAt: now, startedAt: now - 20000, after, modelLabel: 'Sonnet 5.5', effort: 'high' }; tasks.push(t); return t; };
for (const b of ['Builder A', 'Builder B', 'Builder C', 'Builder D']) { const B = byName(b); if (!B) continue; const v = mk('Verifier ' + b.slice(-1), B.id, 2, 'checks the claims in version ' + b.slice(-1)); task(B.id, v.id, 'running', 'Verify: version ' + b.slice(-1)); const f = mk('Fact-checker ' + b.slice(-1), v.id, 3, 'checks each source'); task(v.id, f.id, k % 3 ? 'running' : 'queued', 'Check sources ' + b.slice(-1)); if (k % 2) { const r = mk('Reader ' + b.slice(-1), f.id, 4, 'reads one source in full'); task(f.id, r.id, 'running', 'Read source ' + b.slice(-1)); } }
const j1 = byName('Judge 1'); if (j1) { const v = mk('Verifier J', j1.id, 2, 'reruns the scores'); task(j1.id, v.id, 'done', 'Re-score'); }
while (extra.length + have.length < 35) { const s2 = mk('Scout ' + (9 + k), lead, 1, 'one more angle'); task(lead, s2.id, k % 3 ? 'running' : 'done', 'Scout: angle ' + k); }
st.setState(x => ({ chats: x.chats.map(c => c.id === chatId ? { ...c, agents: [...(c.agents || []), ...extra] } : c), members: { ...x.members, ...Object.fromEntries(extra.map(a => [a.id, a])) }, tasks: { ...x.tasks, [chatId]: [...(x.tasks[chatId] || []), ...tasks] }, agents: { ...x.agents, ...Object.fromEntries(tasks.filter(t => t.status === 'running').map(t => [chatId + ':' + t.to, { chatId, accountId: t.to, phase: 'thinking', activity: 'Reading the source', queued: 0, turnStartedAt: now - 20000 }])) } }));
window.__S().setView('flow');
await window.__sleep(2400);
return 'stress: present ' + (have.length + extra.length) + ' | ' + window.__info();
